static int lbs_ethtool_set_wol ( struct net_device * dev , struct ethtool_wolinfo * wol ) { struct lbs_private * priv = dev -> ml_priv ; if ( wol -> wolopts & ~ ( WAKE_UCAST | WAKE_MCAST | WAKE_BCAST | WAKE_PHY ) ) { return - EOPNOTSUPP ; } if ( wol -> wolopts & WAKE_UCAST ) { priv -> wol_criteria |= EHS_WAKE_ON_UNICAST_DATA ; } if ( wol -> wolopts & WAKE_MCAST ) { priv -> wol_criteria |= EHS_WAKE_ON_MULTICAST_DATA ; } if ( wol -> wolopts & WAKE_BCAST ) { priv -> wol_criteria |= EHS_WAKE_ON_BROADCAST_DATA ; } if ( wol -> wolopts & WAKE_PHY ) { priv -> wol_criteria |= EHS_WAKE_ON_MAC_EVENT ; } if ( wol -> wolopts == 0 ) { priv -> wol_criteria |= EHS_REMOVE_WAKEUP ; } return 0 ; } const struct ethtool_ops lbs_ethtool_ops = { . get_drvinfo = lbs_ethtool_get_drvinfo . get_eeprom = lbs_ethtool_get_eeprom . get_eeprom_len = lbs_ethtool_get_eeprom_len . get_sset_count = lbs_mesh_ethtool_get_sset_count . get_ethtool_stats = lbs_mesh_ethtool_get_stats . get_strings = lbs_mesh_ethtool_get_strings . get_wol = lbs_ethtool_get_wol . set_wol = lbs_ethtool_set_wol } ; 